import {uid,clone,createLayer,validateDocument} from './model.js';
import {canvas,maskCanvas} from './renderer.js';
import {pathToWorld,setWorldPath,pathNodes,nodesPath,translateNode,tracePath,selectionPath} from './path-core.js';
import {assertCanEdit} from './layer-policy.js';
import {downloadBlob} from './storage.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createDocumentTools(api){const $=s=>document.querySelector(s);let alphaId=null,stroke=null,drag=null,lastDoc=null;
 const safe=fn=>{try{return fn();}catch(e){api.toast(e.message,true);}},currentAlpha=()=>api.doc()?.alphaChannels?.find(c=>c.id===alphaId);
 function target(){const d=api.doc(),p=d.paths?.find(p=>p.id===d.activePathId),l=api.layer();return p?{saved:true,item:p,commands:p.commands}:l?.path?{saved:false,item:l,commands:pathToWorld(l)}:null;}
 function store(t,commands){if(t.saved)t.item.commands=clone(commands);else{assertCanEdit(api.doc(),[t.item],'geometry');assertCanEdit(api.doc(),[t.item],'pixels');const next=clone(t.item);setWorldPath(next,commands);validateDocument({...api.doc(),layers:api.doc().layers.map(l=>l===t.item?next:l)});Object.assign(t.item,next);}}
 function savePath(commands,name='Saved Path',kind='saved'){const d=api.doc();d.paths||=[];const old=kind==='work'&&d.paths.find(p=>p.kind==='work');if(old){old.commands=clone(commands);d.activePathId=old.id;}else{if(d.paths.length>=64)throw Error('Tối đa64 đường.');const p={id:uid(),name:name.slice(0,200),kind,commands:clone(commands),fillRule:'nonzero'};d.paths.push(p);d.activePathId=p.id;}api.commit('Save path');}
 function saveAlpha(){const d=api.doc();if(!d.selection)throw Error('Tạo vùng chọn trước khi lưu alpha.');d.alphaChannels||=[];if(d.alphaChannels.length>=16)throw Error('Tối đa16 kênh alpha.');const c={id:uid(),name:'Alpha '+(d.alphaChannels.length+1),mask:clone(d.selection)};d.alphaChannels.push(c);alphaId=c.id;api.commit('Save alpha channel');}
 function loadAlpha(id,mode='replace'){const d=api.doc(),c=d.alphaChannels?.find(c=>c.id===id);if(!c)return;let out=maskCanvas(d,c.mask,1,api.assets);if(mode!=='replace'&&d.selection){const before=maskCanvas(d,d.selection,1,api.assets),x=before.getContext('2d');x.globalCompositeOperation={add:'source-over',subtract:'destination-out',intersect:'destination-in'}[mode];x.drawImage(out,0,0);out=before;}const source=out.toDataURL();api.assets.set(source,out);d.selection={type:'paint',source,x:0,y:0,width:d.width,height:d.height,feather:0};alphaId=null;api.commit('Load alpha selection');}
 function rename(p,kind){api.showModal('Đổi tên '+kind,'Tên được lưu trong dự án.',`<label class="modal-field">Tên<input id="asset-name" maxlength="200" value="${esc(p.name)}"></label>`,[{label:'Hủy',run:()=>api.closeModal(true)},{label:'Lưu',primary:true,run:()=>{p.name=$('#asset-name').value.slice(0,200)||kind;if(p.kind==='work')p.kind='saved';api.closeModal();api.commit('Rename '+kind);}}]);}
 function alphaOptions(id){const d=api.doc(),c=d.alphaChannels.find(c=>c.id===id);api.showModal(c.name,'Kênh alpha độc lập với màu ảnh xuất.',`<div class="studio-button-grid">${[['load','Nạp vùng chọn'],['invert','Đảo trắng/đen'],['copy','Nhân bản'],['rename','Đổi tên'],['export','Xuất PNG xám'],['delete','Xóa kênh']].map(([id,n])=>`<button class="button" id="alpha-${id}">${n}</button>`).join('')}</div>`,[{label:'Đóng',run:()=>api.closeModal()}],()=>{for(const op of ['load','invert','copy','rename','export','delete'])$('#alpha-'+op).onclick=()=>safe(()=>{if(op==='load'){api.closeModal();loadAlpha(id);return;}if(op==='rename'){api.closeModal();rename(c,'kênh');return;}if(op==='export'){const out=maskCanvas(d,c.mask,1,api.assets),x=out.getContext('2d'),p=x.getImageData(0,0,out.width,out.height);for(let i=0;i<p.data.length;i+=4){p.data[i]=p.data[i+1]=p.data[i+2]=p.data[i+3];p.data[i+3]=255;}x.putImageData(p,0,0);out.toBlob(b=>downloadBlob(b,'alpha.png'),'image/png');return;}if(op==='invert')c.mask.invert=!c.mask.invert;if(op==='copy'){if(d.alphaChannels.length>=16)throw Error('Tối đa16 kênh.');d.alphaChannels.push({...clone(c),id:uid(),name:(c.name+' copy').slice(0,200)});}if(op==='delete'){d.alphaChannels=d.alphaChannels.filter(c=>c.id!==id);if(alphaId===id)alphaId=null;}api.closeModal();api.commit('Edit alpha channel');});});}
 function channelRows(root){const d=api.doc();root.insertAdjacentHTML('beforeend',`<div class="document-assets-head">KÊNH ALPHA ĐÃ LƯU <button data-alpha-save title="Lưu vùng chọn">＋</button></div><p class="dock-caption">Tô trắng/đen bằng B/E. Chọn RGB để trở về ảnh.</p>${(d.alphaChannels||[]).map(c=>`<div class="alpha-item ${c.id===alphaId?'active':''}"><button data-alpha-view="${c.id}" aria-pressed="${c.id===alphaId}"><canvas width="48" height="32" data-alpha-thumb="${c.id}"></canvas><span>${esc(c.name)}</span></button><button data-alpha-load="${c.id}" title="Nạp · Shift thêm · Alt trừ · Shift+Alt giao">↗</button><button data-alpha-more="${c.id}" aria-label="Tùy chọn ${esc(c.name)}">•••</button></div>`).join('')}`);
 for(const c of d.alphaChannels||[]){const thumb=root.querySelector(`[data-alpha-thumb="${c.id}"]`),x=thumb.getContext('2d'),m=maskCanvas(d,c.mask,Math.min(48/d.width,32/d.height),api.assets);x.fillStyle='#000';x.fillRect(0,0,48,32);x.drawImage(m,0,0,48,32);}root.querySelector('[data-alpha-save]').onclick=()=>safe(saveAlpha);root.querySelectorAll('[data-alpha-view]').forEach(b=>b.onclick=()=>{alphaId=b.dataset.alphaView;api.setChannel('composite');api.refreshPanels();api.requestRender();});root.querySelectorAll('[data-alpha-load]').forEach(b=>b.onclick=e=>loadAlpha(b.dataset.alphaLoad,e.shiftKey&&e.altKey?'intersect':e.altKey?'subtract':e.shiftKey?'add':'replace'));root.querySelectorAll('[data-alpha-more]').forEach(b=>b.onclick=()=>alphaOptions(b.dataset.alphaMore));}
 function toSelection(){const t=target(),d=api.doc();if(!t)throw Error('Chọn đường trước.');const out=canvas(d.width,d.height),x=out.getContext('2d');tracePath(x,t.commands);x.fillStyle='#fff';x.fill(t.item.fillRule||'nonzero');const source=out.toDataURL();api.assets.set(source,out);d.selection={type:'paint',source,x:0,y:0,width:d.width,height:d.height,feather:0};alphaId=null;api.commit('Path to selection');}
 function editPoints(){const t=target();if(!t)throw Error('Chọn đường trước.');if(!t.saved){assertCanEdit(api.doc(),[t.item],'geometry');assertCanEdit(api.doc(),[t.item],'pixels');}const original=clone(t.item),subs=pathNodes(t.commands);let index=0;const refs=()=>subs.flatMap(s=>s.nodes.map((n,i)=>({s,n,i}))),rollback=()=>{for(const k of Object.keys(t.item))delete t.item[k];Object.assign(t.item,original);api.renderUI();api.requestRender();},apply=()=>safe(()=>{if(!t.saved)Object.assign(t.item,clone(original));store(t,nodesPath(subs));api.requestRender();api.overlay();});
 api.showModal('Sửa điểm Bézier',t.item.name,'<div id="anchor-controls"></div><p class="dock-caption">Direct Selection A kéo điểm trên ảnh. Alt-kéo tách tay nắm.</p>',[{label:'Hủy',run:()=>api.closeModal(true)},{label:'Lưu đường',primary:true,run:()=>{api.closeModal();api.commit('Edit path anchors');}}],()=>{function ui(){const all=refs();index=Math.max(0,Math.min(all.length-1,index));const r=all[index];$('#anchor-controls').innerHTML=`<label class="modal-field">Điểm<select id="anchor-index">${all.map((n,i)=>`<option value="${i}" ${i===index?'selected':''}>${i+1}</option>`).join('')}</select></label><div class="modal-grid">${['x','y','inX','inY','outX','outY'].map(k=>`<label class="modal-field">${k}<input data-anchor="${k}" aria-label="Anchor ${k}" type="number" step=".1" value="${r.n[k]}"></label>`).join('')}</div><label><input type="checkbox" id="path-closed" ${r.s.closed?'checked':''}> Đường khép</label><div class="studio-button-grid"><button class="button" id="anchor-add">Thêm điểm giữa</button><button class="button" id="anchor-delete">Xóa điểm</button></div>`;$('#anchor-index').onchange=e=>{index=Number(e.target.value);ui();};$('#anchor-controls').querySelectorAll('[data-anchor]').forEach(el=>el.oninput=()=>{const k=el.dataset.anchor,v=Number(el.value);if(!Number.isFinite(v)||Math.abs(v)>1e7)return;if(k==='x'||k==='y')translateNode(r.n,k==='x'?v:r.n.x,k==='y'?v:r.n.y);else r.n[k]=v;apply();});$('#path-closed').onchange=e=>{r.s.closed=!!e.target.checked;apply();};$('#anchor-add').onclick=()=>{if(!r.s.closed&&r.i===r.s.nodes.length-1)return;const a=r.n,b=r.s.nodes[(r.i+1)%r.s.nodes.length],mid=(p,q)=>[(p[0]+q[0])/2,(p[1]+q[1])/2],q0=mid([a.x,a.y],[a.outX,a.outY]),q1=mid([a.outX,a.outY],[b.inX,b.inY]),q2=mid([b.inX,b.inY],[b.x,b.y]),r0=mid(q0,q1),r1=mid(q1,q2),p=mid(r0,r1);a.outX=q0[0];a.outY=q0[1];b.inX=q2[0];b.inY=q2[1];r.s.nodes.splice(r.i+1,0,{x:p[0],y:p[1],inX:r0[0],inY:r0[1],outX:r1[0],outY:r1[1]});apply();ui();};$('#anchor-delete').onclick=()=>{if(r.s.nodes.length<=(r.s.closed?3:2))return;r.s.nodes.splice(r.i,1);apply();ui();};}ui();},rollback);}
 function pathOptions(id){const d=api.doc(),p=d.paths.find(p=>p.id===id);d.activePathId=id;api.showModal(p.name,'Đường độc lập · không thay ảnh cho đến khi tạo layer/vùng chọn.',`<div class="studio-button-grid">${[['rename','Đổi tên / Lưu Work Path'],['copy','Nhân bản'],['layer','Tạo lớp vector'],['points','Thông số điểm'],['delete','Xóa đường']].map(([id,n])=>`<button class="button" id="path-${id}">${n}</button>`).join('')}</div>`,[{label:'Đóng',run:()=>api.closeModal()}],()=>{for(const op of ['rename','copy','layer','points','delete'])$('#path-'+op).onclick=()=>safe(()=>{if(op==='layer'){const l=createLayer('shape',{name:p.name,shape:'path',path:clone(p.commands),pathWidth:d.width,pathHeight:d.height,width:d.width,height:d.height,color:api.foreground()});validateDocument({...d,layers:[...d.layers,l]});d.activePathId=null;api.closeModal();api.addLayer(l,'Path to vector layer');return;}api.closeModal();if(op==='rename')rename(p,'đường');if(op==='copy')savePath(p.commands,p.name+' copy');if(op==='points')editPoints();if(op==='delete'){d.paths=d.paths.filter(x=>x.id!==id);d.activePathId=null;api.commit('Delete path');}});});}
 function savedRows(root){const d=api.doc();root.insertAdjacentHTML('beforeend',`<div class="document-assets-head">WORK PATH & ĐƯỜNG ĐÃ LƯU</div>${(d.paths||[]).map(p=>`<div class="saved-path-row ${p.id===d.activePathId?'active':''}"><button data-saved-path="${p.id}">${esc(p.name)}<small>${p.kind==='work'?'Work Path':'Đã lưu'} · ${pathNodes(p.commands).reduce((n,s)=>n+s.nodes.length,0)} điểm</small></button><button data-saved-options="${p.id}">•••</button></div>`).join('')}<div class="path-edit-actions">${[['path-save-layer','Lưu đường của lớp'],['path-edit','Sửa điểm trên ảnh · A'],['path-points','Thông số điểm'],['path-from-selection','Vùng chọn → Work Path'],['path-to-selection','Đường → vùng chọn']].map(([id,n])=>`<button class="button" data-doc-op="${id}">${n}</button>`).join('')}</div>`);root.querySelectorAll('[data-saved-path]').forEach(b=>b.onclick=()=>{d.activePathId=b.dataset.savedPath;alphaId=null;api.setTool('node');api.refreshPanels();api.overlay();});root.querySelectorAll('[data-saved-options]').forEach(b=>b.onclick=()=>pathOptions(b.dataset.savedOptions));root.querySelectorAll('[data-doc-op]').forEach(b=>b.onclick=()=>safe(()=>actions[b.dataset.docOp]()));}
 function paint(p){const g=stroke,x=g.coverage.getContext('2d');x.strokeStyle=x.fillStyle='#fff';x.lineWidth=g.size;x.lineCap='round';x.beginPath();if(Math.hypot(p.x-g.last.x,p.y-g.last.y)<.001){x.arc(p.x,p.y,g.size/2,0,2*Math.PI);x.fill();}else{x.moveTo(g.last.x,g.last.y);x.lineTo(p.x,p.y);x.stroke();}g.last=p;const r=g.size/2+2,b=g.bounds,d=api.doc();g.bounds={x:Math.max(0,Math.floor(Math.min(p.x-r,g.first.x-r,b?.x??Infinity))),y:Math.max(0,Math.floor(Math.min(p.y-r,g.first.y-r,b?.y??Infinity))),right:Math.min(d.width,Math.ceil(Math.max(p.x+r,b?.right??-Infinity))),bottom:Math.min(d.height,Math.ceil(Math.max(p.y+r,b?.bottom??-Infinity)))};const q=g.bounds,w=q.right-q.x,h=q.bottom-q.y;if(w<1||h<1)return;const values=x.getImageData(q.x,q.y,w,h);for(let i=3;i<values.data.length;i+=4)values.data[i]=Math.round(values.data[i]*g.opacity);g.weight.getContext('2d').putImageData(values,q.x,q.y);const out=g.out.getContext('2d');out.clearRect(0,0,g.out.width,g.out.height);out.drawImage(g.base,0,0);out.save();out.globalCompositeOperation=g.erase?'destination-out':'source-over';out.drawImage(g.weight,0,0);out.restore();api.requestRender();}
 function pointerDown(e,p){const d=api.doc(),c=currentAlpha();if(c&&['brush','eraser'].includes(api.tool())){stroke={item:c,base:maskCanvas(d,c.mask,1,api.assets),coverage:canvas(d.width,d.height),weight:canvas(d.width,d.height),out:canvas(d.width,d.height),size:api.brushSize(),opacity:api.brushOpacity()/100,last:p,first:p,erase:api.tool()==='eraser'};paint(p);return true;}if(api.tool()!=='node')return false;const t=target();if(!t)return true;try{if(!t.saved){assertCanEdit(d,[t.item],'geometry');assertCanEdit(d,[t.item],'pixels');}}catch(e){api.toast(e.message,true);return true;}const subs=pathNodes(t.commands),hits=[];subs.forEach((s,si)=>s.nodes.forEach((n,ni)=>{for(const part of ['anchor','in','out']){const x=part==='anchor'?n.x:n[part+'X'],y=part==='anchor'?n.y:n[part+'Y'],dist=Math.hypot(x-p.x,y-p.y)*api.zoom();if(dist<9)hits.push({si,ni,part,dist:dist+(part==='anchor'?0:1)});}}));hits.sort((a,b)=>a.dist-b.dist);if(hits.length)drag={target:t,original:clone(t.item),subs,hit:hits[0]};return true;}
 function pointerMove(e,p){if(stroke){paint(p);return true;}if(drag){const g=drag,n=g.subs[g.hit.si].nodes[g.hit.ni];translateNode(n,p.x,p.y,g.hit.part,!e.altKey);if(!g.target.saved)Object.assign(g.target.item,clone(g.original));safe(()=>store(g.target,nodesPath(g.subs)));api.requestRender();api.overlay();return true;}return false;}
 function pointerUp(){if(stroke){const g=stroke;stroke=null;const source=g.out.toDataURL();api.assets.set(source,g.out);g.item.mask={type:'paint',source,x:0,y:0,width:api.doc().width,height:api.doc().height,feather:0};api.commit('Paint alpha channel');return true;}if(drag){drag=null;api.commit('Move path anchor');return true;}return false;}
 function cancel(){if(stroke){stroke=null;api.requestRender();return true;}if(drag){Object.assign(drag.target.item,drag.original);drag=null;api.requestRender();api.overlay();return true;}return false;}
 function overlay(ctx,z){if(api.tool()!=='node'&&!api.doc()?.activePathId)return;const t=target();if(!t)return;ctx.save();ctx.lineWidth=1.2/z;ctx.strokeStyle='#bbadff';tracePath(ctx,t.commands);ctx.stroke();for(const s of pathNodes(t.commands))for(const n of s.nodes){ctx.beginPath();ctx.moveTo(n.inX,n.inY);ctx.lineTo(n.x,n.y);ctx.lineTo(n.outX,n.outY);ctx.stroke();for(const[x,y]of [[n.x,n.y],[n.inX,n.inY],[n.outX,n.outY]]){ctx.fillStyle='#e9e2ff';ctx.fillRect(x-3/z,y-3/z,6/z,6/z);}}ctx.restore();}
 function preview(c){const item=currentAlpha();if(!item)return;const m=stroke?.item===item?stroke.out:maskCanvas(api.doc(),item.mask,c.width/api.doc().width,api.assets),x=c.getContext('2d');x.clearRect(0,0,c.width,c.height);x.fillStyle='#000';x.fillRect(0,0,c.width,c.height);x.drawImage(m,0,0,c.width,c.height);}
 const actions={'alpha-save':saveAlpha,'alpha-load':()=>{if(!alphaId)throw Error('Chọn kênh alpha.');loadAlpha(alphaId);},'path-save-layer':()=>{if(!api.layer()?.path)throw Error('Chọn lớp vector.');savePath(pathToWorld(api.layer()),api.layer().name);},'path-from-selection':()=>{if(!api.doc().selection)throw Error('Tạo vùng chọn.');savePath(selectionPath(api.doc().selection),'Work Path','work');},'path-to-selection':toSelection,'path-edit':()=>{alphaId=null;api.setTool('node');api.overlay();},'path-points':editPoints};
 return{actions,actionItems:[['alpha-save','Lưu vùng chọn vào kênh alpha','mask',''],['alpha-load','Nạp kênh alpha thành vùng chọn','select',''],['path-save-layer','Lưu đường Bézier độc lập','pen',''],['path-from-selection','Vùng chọn thành Work Path','pen',''],['path-to-selection','Đường thành vùng chọn','select',''],['path-edit','Direct Selection · sửa điểm neo','pen','A'],['path-points','Thông số điểm neo & tay nắm','pen','']],channelRows,savedRows,pointerDown,pointerMove,pointerUp,cancel,overlay,preview,currentAlpha,savePath,loadAlpha,update(){if(lastDoc!==api.doc()?.id){alphaId=null;lastDoc=api.doc()?.id;}if(alphaId&&!currentAlpha())alphaId=null;},exitAlpha(){alphaId=null;api.requestRender();},clearPath(){api.doc().activePathId=null;}};
}
